import ghidra.pcode.exec.*;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
public class C6000ClosedCallTraceTest extends GhidraScript {
 BytesPcodeArithmetic arithmetic;
 long read(BytesPcodeExecutorState state,Varnode node){return arithmetic.toLong(state.getVar(node,PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);}
 long reg(BytesPcodeExecutorState state,String name){return arithmetic.toLong(state.getVar(currentProgram.getRegister(name),PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);}
 long mem(BytesPcodeExecutorState state,long at){return arithmetic.toLong(state.getVar(toAddr(at),4,false,PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);}
 void equal(Object wanted,Object actual,String why){if(!Objects.equals(wanted,actual))throw new AssertionError(why+" expected="+wanted+" actual="+actual);}
 long n(JsonObject row,String key){return row.get(key).getAsLong();}
 String hash(long first,long end)throws Exception{long start=first&~31L;byte[] bytes=new byte[(int)(((end+31)&~31L)-start)];currentProgram.getMemory().getBytes(toAddr(start),bytes);return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}
 protected void run()throws Exception {
  c6000.C6000PacketContext.prime(currentProgram,monitor);arithmetic=BytesPcodeArithmetic.forLanguage(currentProgram.getLanguage());var cases=JsonParser.parseString(Files.readString(Paths.get(getScriptArgs()[0]))).getAsJsonArray();var records=new JsonArray();int accepted=0,refused=0;
  for(var element:cases){var row=element.getAsJsonObject();long c=n(row,"caller"),f=n(row,"callee");String name=row.get("name").getAsString();currentProgram.getFunctionManager().createFunction(name,toAddr(c),new AddressSet(toAddr(c),toAddr(n(row,"caller_end")-1)),SourceType.USER_DEFINED);currentProgram.getFunctionManager().createFunction(name+"_callee",toAddr(f),new AddressSet(toAddr(f),toAddr((name.equals("declared_unowned_tail")||name.equals("missing_unowned_span")?f+16:name.equals("owned_body_mid_instruction")?f+0x1a:name.equals("span_starts_mid_instruction")?f+0x19:n(row,"callee_end"))-1)),SourceType.USER_DEFINED);}
  for(var element:cases){var row=element.getAsJsonObject();long c=n(row,"caller"),f=n(row,"callee");String name=row.get("name").getAsString();var caller=currentProgram.getFunctionManager().getFunctionAt(toAddr(c));var callee=currentProgram.getFunctionManager().getFunctionAt(toAddr(f));String oldCaller=caller.getBody().toString(),oldCallee=callee.getBody().toString();setEOLComment(toAddr(c+4),"call annotation remains owned by caller");setEOLComment(toAddr(f),"callee annotation remains owned by callee");
   if(name.equals("data_in_instruction_suffix"))createData(toAddr(f+0x1a),ghidra.program.model.data.ByteDataType.dataType);
   if(name.equals("stale_compact_context"))for(String field:List.of("c_is16","c_isheader","c_hdrpkt","c_rs","c_dsz","c_prot","c_br","c_sat","c_pfollow"))currentProgram.getProgramContext().setValue(currentProgram.getRegister(field),toAddr(f),toAddr(f),java.math.BigInteger.valueOf(field.equals("c_is16")?0:1));
   String callerHash=hash(c,n(row,"caller_end"));if(name.equals("bad_hash"))callerHash=(callerHash.startsWith("0")?"1":"0")+callerHash.substring(1);
   var callerWindow=new c6000.C6000PipelineCompiler.TraceWindow(name.equals("wrong_owner")?f:c,c,n(row,"caller_end"),callerHash);var gaps=name.equals("span_starts_mid_instruction")?List.of(new c6000.C6000PipelineCompiler.UnownedSpan(f+0x19,n(row,"callee_end"),"Deliberately partial instruction span")):name.equals("declared_unowned_tail")||name.equals("claimed_gap_has_owner")?List.of(new c6000.C6000PipelineCompiler.UnownedSpan(f+16,n(row,"callee_end"),"Explicit synthetic listing gap, no function adoption")):List.<c6000.C6000PipelineCompiler.UnownedSpan>of();var calleeWindow=new c6000.C6000PipelineCompiler.TraceWindow(f,f,n(row,"callee_end"),hash(f,n(row,"callee_end")),gaps);
   Long stop=name.equals("bad_stop")?Long.valueOf(n(row,"caller_end")):null;Long callerReturn=stop==null?Long.valueOf(n(row,"caller_return")):null;
   var plan=new c6000.C6000PipelineCompiler.ClosedCallPlan(currentProgram.getLanguageID().getIdAsString(),callerWindow,calleeWindow,c,stop,n(row,"call"),n(row,"link"),n(row,"continuation"),n(row,"callee_return"),callerReturn,new c6000.C6000PipelineCompiler.TraceEntry(!name.equals("not_drained"),Set.of()),"Synthetic caller saves and restores its entry B3; exact known call/link/callee return; fresh drained entry");
   c6000.C6000PipelineCompiler.ClosedCallTraceResult result;
   try{result=c6000.C6000PipelineCompiler.compileClosedCallTrace(currentProgram,caller,plan);if(row.has("refused"))throw new AssertionError("Accepted "+name);accepted++;}catch(IllegalArgumentException error){if(!row.has("refused")||!error.getMessage().contains(row.get("refused").getAsString()))throw new AssertionError(name+" unexpected refusal "+error);row.addProperty("error",error.getMessage());records.add(row);println("EXPECTED_REFUSAL "+name+" "+error.getMessage());refused++;continue;}
   if(name.equals("stale_compact_context")){equal(java.math.BigInteger.ONE,currentProgram.getProgramContext().getValue(currentProgram.getRegister("c_rs"),toAddr(f),false),"stored context not mutated");equal(java.math.BigInteger.ZERO,currentProgram.getProgramContext().getValue(currentProgram.getRegister("c_is16"),toAddr(f),false),"stored width not mutated");}
   equal(oldCaller,caller.getBody().toString(),"caller body stable");equal(oldCallee,callee.getBody().toString(),"callee body stable");equal("call annotation remains owned by caller",getEOLComment(toAddr(c+4)),"caller annotation");equal("callee annotation remains owned by callee",getEOLComment(toAddr(f)),"callee annotation");
   boolean ordinaryRefused=false;try{new c6000.C6000PipelineCompiler(currentProgram,caller).compile();}catch(IllegalArgumentException error){if(!error.getMessage().contains("flow enters another function"))throw error;ordinaryRefused=true;}if(!ordinaryRefused)throw new AssertionError("Ordinary compiler accepted undeclared callee");
   var state=new BytesPcodeExecutorState(currentProgram.getLanguage(),PcodeStateCallbacks.NONE);for(var register:currentProgram.getLanguage().getRegisters())if(!register.isProcessorContext()&&register.getMinimumByteSize()==4)state.setVar(register,arithmetic.fromConst(0,4));for(var item:Map.of("B3",0x9000L,"B15",0x8100L,"A2",2L,"A3",3L,"A4",0x11112222L,"A5",0x33334444L,"B4",0x12345678L,"A6",0x8200L,"B7",0L,"A7",0x8300L).entrySet())state.setVar(currentProgram.getRegister(item.getKey()),arithmetic.fromConst(item.getValue(),4));state.setVar(toAddr(0x8100),0x300,false,new byte[0x300]);
   var schedule=result.schedule();var executor=new PcodeExecutor<byte[]>(state,PcodeExecutorStatePiece.Reason.EXECUTE_READ);var library=PcodeUseropLibrary.<byte[]>nil();var frame=executor.begin(Arrays.asList(schedule.code()),library.getSymbols((ghidra.app.plugin.processors.sleigh.SleighLanguage)currentProgram.getLanguage()));var points=new HashMap<Integer,c6000.C6000PipelineCompiler.ClosedCallBoundary>();for(var point:result.boundaries())points.put(point.pcodeIndex(),point);int cycles=0,steps=0,stalls=0;var kinds=new ArrayList<String>();
   while(!frame.isFinished()&&steps++<100000){int index=frame.index();if(schedule.cycleStarts().containsKey(index))cycles++;if(schedule.stallTargets().containsKey(index))stalls++;var point=points.get(index);if(point!=null){kinds.add(point.kind());long target=read(state,point.capturedTarget());equal(point.expectedTarget()==null?0x9000L:point.expectedTarget(),target,"captured "+point.kind()+" target");if(point.kind().equals("CALL_ENTER")){equal(0,point.effects().size(),"call entry drained late effects");var b3=point.hazards().stream().filter(h->h.register().equals("B3")).findFirst().orElseThrow();equal(1L,read(state,b3.enabled()),"ADDKPC recent B3 hazard kept");}if(point.kind().equals("CALL_RETURN")){equal(1,point.effects().size(),"late callee operation remains in flight");if(!name.equals("captured_store"))equal(3,point.effects().get(0).remainingAdvances(),"MPYLI remaining advances");if(name.equals("captured_store")){equal(2,point.effects().get(0).remainingAdvances(),"STW remaining advances");equal(1,point.stores().size(),"captured pending store");equal(0x8200L,read(state,point.stores().get(0).address()),"captured store address");equal(0x12345678L,read(state,point.stores().get(0).value()),"captured store data");}}}executor.step(frame,library);}
   if(!frame.isFinished())throw new AssertionError("closed trace did not finish");equal(List.of("CALL_ENTER","CALL_RETURN","CALLER_RETURN"),kinds,"closed boundaries");equal(n(row,"continuation"),reg(state,"A1"),"callee cross-path link capture");equal(0x9000L,reg(state,"B3"),"caller restored old return link");equal(0x8100L,reg(state,"B15"),"caller restored stack base");equal(0x9000L,reg(state,"PC"),"actual caller return");equal(0x9000L,mem(state,0x8100),"saved entry link");equal(Set.of(),result.outgoingE1Writes(),"drained caller return hazards");if(name.equals("stale_compact_context")){equal(0x8201L,reg(state,"A6"),"raw RS0 compact destination");equal(0L,reg(state,"A22"),"stale stored RS1 destination untouched");}
   if(name.equals("captured_store")){equal(0x12345678L,mem(state,0x8200),"tail store retained old value/address");equal(0L,mem(state,0x8300),"tail did not resample address");}else{equal(0x11112222L,reg(state,"A8"),"caller first EP sees old MPYLI low word");equal(6L,reg(state,"A9"),"later caller sees E4 MPYLI result");equal(0L,reg(state,"A5"),"MPYLI high result");}
   row.addProperty("cycles",cycles);row.addProperty("stallMarkers",stalls);row.addProperty("closed",true);records.add(row);println("CLOSED_CALL_CASE "+name+" cycles="+cycles+" stalls="+stalls);
  }Files.writeString(Paths.get(getScriptArgs()[1]),new GsonBuilder().setPrettyPrinting().create().toJson(records));println("CLOSED_CALL_TRACE_TEST_OK accepted="+accepted+" refused="+refused);
 }
}
